#include <stdlib.h>

char* getPermutation(int n, int k) {
    int *nums = (int*)malloc((size_t)n * sizeof(int));
    char *ans = (char*)malloc((size_t)n + 1);
    int fact = 1;

    for (int i = 1; i <= n - 1; ++i) fact *= i;
    for (int i = 0; i < n; ++i) nums[i] = i + 1;

    --k;
    int size = n;
    int pos = 0;

    while (size > 0) {
        int index = k / fact;
        ans[pos++] = (char)('0' + nums[index]);

        for (int j = index; j < size - 1; ++j)
            nums[j] = nums[j + 1];

        --size;
        k %= fact;
        if (size > 0) fact /= size;
    }

    ans[pos] = '\0';
    free(nums);
    return ans;
}

